using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using System.Text.Json;
public sealed record McpToolRequest(string Tool,JsonElement Arguments);public sealed record McpToolResponse(string Tool,string Status,object Result);
[ApiController,Route("api/v1/mcp"),Authorize]public sealed class McpController(McpToolRouter router):ControllerBase{[HttpGet("tools")]public IActionResult Tools()=>Ok(router.List());[HttpPost("tools/call")]public async Task<ActionResult<McpToolResponse>>Call(McpToolRequest request,CancellationToken ct){var result=await router.ExecuteAsync(request.Tool,request.Arguments,ct);return Ok(new McpToolResponse(request.Tool,"Completed",result));}}